    public static String goNext(Runner player, Random random, Case[][] cases) {
        System.err.println(player.x + " " + player.y);
        ArrayList<String> possibleMoves = new ArrayList<>();
        Case up = getCaseFromCoordinates(player.x, player.y - 1, cases);
        Case right = getCaseFromCoordinates(player.x + 1, player.y, cases);
        Case down = getCaseFromCoordinates(player.x, player.y + 1, cases);
        Case left = getCaseFromCoordinates(player.x - 1, player.y, cases);
